_uh3 = _tf25.mkdtemp()
_un3 = _uns(_uh3)
_t0 = _un3["_USAGE_T0"]
with open(os.path.join(_uh3, "quality.jsonl"), "w") as _fh:
    _fh.write(json.dumps({"ts": int(_t0 - 7200), "tier": "Fast", "model": "Gemma 4 26B",
                          "searched": False, "chars": 400}) + "\n")
