# every settings key the page posts is one a set names: an unnamed key
# would be dropped by split_prefs, and a feature would quietly stop saving
def _bal8(s_, i_):
    d_ = 0
    for j_ in range(i_, len(s_)):
        d_ += {"(": 1, ")": -1}.get(s_[j_], 0)
        if d_ == 0:
            return s_[i_ + 1:j_]
    return ""


