_svm = []
for _d34, _o34, _nw34 in _SV_MUT:
    if _MILLENAI_SRC.count(_o34) < 1:
        _svm.append((_d34, "anchor missing"))
        continue
    _r34 = _sv_run(_MILLENAI_SRC.replace(_o34, _nw34, 1))
    _svm.append((_d34, [n for n, o, _x in _r34 if not o][:1] or "MISSED"))
